`timescale 1ns/1ps
// HGI unit9/op2. The sorted insertion recurrence is the existing A3 selector's.
// This opt-in engine leaves the legacy DS router/SELECT implementations intact.
// Dispatcher resolves descriptor addresses/strides; streams one row at a time.
// No output of a row precedes validation of all its scores (NaN fail closed).
module ot_hgi_idx_topk #(
 parameter bit ENABLE=0, parameter integer MAX_K=2048,
 parameter bit MUTANT_TIE=0
)(
 input wire clk,rst_n,
 input wire cmd_valid, output wire cmd_ready,
 input wire [3:0] cmd_unit, input wire [5:0] cmd_op,
 input wire [24:0] cmd_param, input wire [31:0] cmd_n,cmd_m,
 input wire cmd_values,
 input wire in_valid, output wire in_ready, input wire [31:0] in_score,
 output wire out_valid, input wire out_ready,
 output wire [31:0] out_id,out_score,out_row,
 output wire out_last, output wire out_values_valid, output reg done, output reg [3:0] error
);
 localparam IDLE=0,FILL=1,EMIT=2,FINISH=3;
 reg [1:0] state;
 reg [31:0] n,m,row,cursor,emit_cursor;
 reg [11:0] k;
 reg values_enabled;
 reg [52:0] cells[0:MAX_K-1];
 reg [31:0] values[0:MAX_K-1];
 wire [31:0] canon=(in_score[30:0]==0)?32'd0:in_score;
 wire [31:0] monotone=canon[31]?~canon:(canon|32'h80000000);
 wire [19:0] index_key=MUTANT_TIE?cursor[19:0]:~cursor[19:0];
 wire [52:0] key={1'b1,monotone,index_key};
 wire nan=(in_score[30:23]==8'hff)&&(in_score[22:0]!=0);
 wire [MAX_K-1:0] greater;
 genvar g;
 generate for(g=0;g<MAX_K;g=g+1) begin:compare
  assign greater[g]=key>cells[g];
 end endgenerate
 assign cmd_ready=state==IDLE;
 assign in_ready=ENABLE&&state==FILL;
 assign out_valid=ENABLE&&state==EMIT;
 assign out_id={{12{1'b0}},MUTANT_TIE?cells[0][19:0]:~cells[0][19:0]};
 assign out_score=values[0];
 assign out_row=row;
 assign out_values_valid=out_valid&&values_enabled;
 assign out_last=state==EMIT&&emit_cursor+1==k;
 integer i;
 always @(posedge clk or negedge rst_n) begin
  if(!rst_n) begin
   state<=IDLE; values_enabled<=0; done<=0;error<=0;n<=0;m<=0;k<=0;row<=0;cursor<=0;emit_cursor<=0;
   for(i=0;i<MAX_K;i=i+1) begin cells[i]<=0; values[i]<=0; end
  end else begin
   done<=0;
   case(state)
    IDLE: if(cmd_valid) begin
     error<=0;
     if(!ENABLE||cmd_unit!=9||cmd_op!=2) begin error<=1;done<=1;end
     else if(cmd_param[24:12]!=0||cmd_param[11:0]==0||cmd_param[11:0]>MAX_K||
       cmd_param[11:0]>cmd_n||cmd_n==0||cmd_n>1048576||cmd_m==0) begin error<=2;done<=1;end
     else begin
      values_enabled<=cmd_values;n<=cmd_n;m<=cmd_m;k<=cmd_param[11:0];row<=0;cursor<=0;state<=FILL;
      for(i=0;i<MAX_K;i=i+1) begin cells[i]<=0;values[i]<=0;end
     end
    end
    FILL: if(in_valid) begin
     if(nan) begin error<=3;done<=1;state<=IDLE;end
     else begin
      for(i=0;i<MAX_K;i=i+1) if(greater[i]) begin
       if(i==0) begin cells[i]<=key;values[i]<=in_score;end
       else if(greater[i-1]) begin cells[i]<=cells[i-1];values[i]<=values[i-1];end
       else begin cells[i]<=key;values[i]<=in_score;end
      end
      cursor<=cursor+1;
      if(cursor+1==n) begin state<=EMIT;emit_cursor<=0;end
     end
    end
    EMIT: if(out_ready) begin
     // Consume the head through the existing local-neighbor shift path.
     // No MAX_K-to-one output mux or global variable-index fanout.
     for(i=0;i<MAX_K-1;i=i+1) begin cells[i]<=cells[i+1];values[i]<=values[i+1];end
     cells[MAX_K-1]<=0;values[MAX_K-1]<=0;
     emit_cursor<=emit_cursor+1;
     if(emit_cursor+1==k) begin
      if(row+1==m) state<=FINISH;
      else begin
       row<=row+1;cursor<=0;state<=FILL;
       for(i=0;i<MAX_K;i=i+1) begin cells[i]<=0;values[i]<=0;end
      end
     end
    end
    FINISH: begin done<=1;state<=IDLE;end
    default:state<=IDLE;
   endcase
  end
 end
endmodule

`timescale 1ns/1ps
// Three registered boundary relays around the measured, byte-identical TOPK core.
// Command, score and result are each captured before boundary logic. A command
// retires only after its final accepted output; faults clear prefetched scores.
module ot_hgi_idx_topk_registered #(
 parameter bit ENABLE=0, parameter integer MAX_K=2048, parameter bit MUTANT_TIE=0,
 parameter bit MUTANT_EARLY_DONE=0
)(
 input wire clk,rst_n,
 input wire cmd_valid, output wire cmd_ready,
 input wire [3:0] cmd_unit, input wire [5:0] cmd_op,
 input wire [24:0] cmd_param, input wire [31:0] cmd_n,cmd_m,
 input wire cmd_values,
 input wire in_valid, output wire in_ready, input wire [31:0] in_score,
 output wire out_valid, input wire out_ready,
 output wire [31:0] out_id,out_score,out_row,
 output wire out_last, output wire out_values_valid, output reg done, output reg [3:0] error
);
 reg active,c_valid,s_valid,q_valid,pending_done;
 reg [3:0] c_unit;
 reg [5:0] c_op;
 reg [24:0] c_param;
 reg [31:0] c_n,c_m,s_score;
 reg c_values;
 reg [31:0] q_id,q_score,q_row;
 reg q_last,q_values;
 wire core_cmd_ready,core_in_ready,core_out_valid,core_done;
 wire [3:0] core_error;
 wire [31:0] core_id,core_score,core_row;
 wire core_last,core_values;
 wire core_out_ready=!q_valid||out_ready;
 assign cmd_ready=!active&&!c_valid&&core_cmd_ready&&!pending_done&&!q_valid;
 assign in_ready=active&&(!s_valid||core_in_ready);
 assign out_valid=q_valid;
 assign out_id=q_id;assign out_score=q_score;assign out_row=q_row;
 assign out_last=q_last;assign out_values_valid=q_valid&&q_values;
 ot_hgi_idx_topk #(.ENABLE(ENABLE),.MAX_K(MAX_K),.MUTANT_TIE(MUTANT_TIE)) core(
  .clk(clk),.rst_n(rst_n),.cmd_valid(c_valid),.cmd_ready(core_cmd_ready),
  .cmd_unit(c_unit),.cmd_op(c_op),.cmd_param(c_param),.cmd_n(c_n),.cmd_m(c_m),.cmd_values(c_values),
  .in_valid(s_valid&&active),.in_ready(core_in_ready),.in_score(s_score),
  .out_valid(core_out_valid),.out_ready(core_out_ready),.out_id(core_id),.out_score(core_score),
  .out_row(core_row),.out_last(core_last),.out_values_valid(core_values),.done(core_done),.error(core_error));
 always @(posedge clk or negedge rst_n)begin
  if(!rst_n)begin
   active<=0;c_valid<=0;s_valid<=0;q_valid<=0;pending_done<=0;done<=0;error<=0;
   c_unit<=0;c_op<=0;c_param<=0;c_n<=0;c_m<=0;c_values<=0;s_score<=0;
   q_id<=0;q_score<=0;q_row<=0;q_last<=0;q_values<=0;
  end else begin
   done<=0;
   if(c_valid&&core_cmd_ready)c_valid<=0;
   if(cmd_valid&&cmd_ready)begin
    active<=1;c_valid<=1;c_unit<=cmd_unit;c_op<=cmd_op;c_param<=cmd_param;
    c_n<=cmd_n;c_m<=cmd_m;c_values<=cmd_values;error<=0;
   end
   if(in_ready)begin
    s_valid<=in_valid;
    if(in_valid)s_score<=in_score;
   end
   if(core_out_ready)begin
    q_valid<=core_out_valid;
    if(core_out_valid)begin
     q_id<=core_id;q_score<=core_score;q_row<=core_row;
     q_last<=core_last;q_values<=core_values;
    end
   end
   if(core_done)begin pending_done<=1;error<=core_error;end
   if((pending_done||core_done)&&((!q_valid||out_ready)||MUTANT_EARLY_DONE))begin
    done<=1;active<=0;pending_done<=0;c_valid<=0;s_valid<=0;
   end
  end
 end
endmodule
